from solution import multiply
import pytest
from hypothesis import given
import hypothesis.strategies as st


def _unit(n: int) -> int:
    return abs(n) % 10


def _expected(a: int, b: int) -> int:
    return _unit(a) * _unit(b)


# ---- explicit spec examples ----
def test_spec_example_148_412_returns_16():
    assert multiply(148, 412) == 16


def test_spec_example_19_28_returns_72():
    assert multiply(19, 28) == 72


def test_spec_example_2020_1851_returns_0():
    assert multiply(2020, 1851) == 0


def test_spec_example_14_neg15_returns_20():
    assert multiply(14, -15) == 20


# ---- properties derived from spec ----
@given(
    a=st.integers(min_value=-10**6, max_value=10**6),
    b=st.integers(min_value=-10**6, max_value=10**6),
)
def test_reference_model_product_of_abs_unit_digits(a, b):
    assert multiply(a, b) == (abs(a) % 10) * (abs(b) % 10)


@given(
    a=st.integers(min_value=-10**6, max_value=10**6),
    b=st.integers(min_value=-10**6, max_value=10**6),
)
def test_sign_invariance_negation_does_not_change_result(a, b):
    # unit digit of -n is unit digit of n (spec: 14,-15 -> 4*5)
    assert multiply(-a, b) == multiply(a, b)
    assert multiply(a, -b) == multiply(a, b)
    assert multiply(-a, -b) == multiply(a, b)


@given(
    a=st.integers(min_value=-10**6, max_value=10**6),
    b=st.integers(min_value=-10**6, max_value=10**6),
)
def test_commutativity(a, b):
    assert multiply(a, b) == multiply(b, a)


@given(
    a=st.integers(min_value=-10**6, max_value=10**6),
    b=st.integers(min_value=-10**6, max_value=10**6),
)
def test_range_between_0_and_81_inclusive(a, b):
    r = multiply(a, b)
    assert isinstance(r, int)
    assert 0 <= r <= 81


@given(
    a=st.integers(min_value=-10**6, max_value=10**6),
    b=st.integers(min_value=-10**6, max_value=10**6),
)
def test_zero_unit_digit_forces_zero(a, b):
    # numbers ending in 0 have unit digit 0, so product is 0
    assert multiply(a * 10, b) == 0
    assert multiply(a, b * 10) == 0
    assert multiply(0, b) == 0
    assert multiply(a, 0) == 0


@given(n=st.integers(min_value=-10**6, max_value=10**6))
def test_single_digit_product_equals_abs_product(n):
    # for |a|,|b| < 10, unit digits are |a|,|b|
    m = st.integers(min_value=-9, max_value=9)  # placeholder to keep signature simple
    for b in (-9, -1, 0, 1, 9):
        assert multiply(n % 10 if False else b, n) == abs(b) * (abs(n) % 10)


@given(a=st.integers(min_value=0, max_value=10**6))
def test_last_decimal_digit_only_matters(a):
    # adding multiples of 10 does not change unit digit
    k1 = st.integers(min_value=-1000, max_value=1000)  # not used directly; keep deterministic
    for k in (-100, -1, 0, 1, 100):
        assert multiply(a + 10 * k, 7) == multiply(a, 7)
        assert multiply(7, a + 10 * k) == multiply(a, 7)


def test_negative_numbers_with_nonzero_remainder():
    # Python's % keeps sign of divisor, so abs(a % 10) != abs(a) % 10 for negatives.
    # Unit digit must be derived from magnitude.
    assert multiply(-14, 15) == 4 * 5
    assert multiply(-19, -28) == 9 * 8
    assert multiply(-11, -11) == 1
    assert multiply(-10, -19) == 0
    assert multiply(-2021, 3) == 1 * 3
    assert multiply(-2020, 7) == 0


def test_trailing_nines_and_zeros_boundaries():
    assert multiply(9, 9) == 81
    assert multiply(-9, -9) == 81
    assert multiply(-9, 9) == 81
    assert multiply(10, 10) == 0
    assert multiply(1000000, 999999) == 0 * 9
    assert multiply(-1000000, -999999) == 0 * 9
